{
    "name": "detain/phlix-plugin-void-bloom-theme",
    "type": "phlix-plugin",
    "description": "Void Bloom — A dark, atmospheric Phlix UI theme with coral accents and deep shadows.",
    "license": "MIT",
    "keywords": [
        "phlix",
        "phlix-plugin",
        "phlix-plugins",
        "ui-theme",
        "theme",
        "dark-theme",
        "coral-accent",
        "void-bloom"
    ],
    "homepage": "https://github.com/detain/phlix-plugin-void-bloom-theme",
    "require": {
        "php": ">=8.3",
        "detain/phlix-shared": "^0.21",
        "psr/container": "^1.1 || ^2.0"
    },
    "require-dev": {
        "phpstan/phpstan": "^2.2",
        "phpunit/phpunit": "^10.0",
        "squizlabs/php_codesniffer": "^4.0"
    },
    "repositories": [
        {
            "type": "vcs",
            "url": "https://github.com/detain/phlix-shared.git"
        }
    ],
    "autoload": {
        "psr-4": {
            "Phlix\\VoidBloom\\": "src/"
        }
    },
    "autoload-dev": {
        "psr-4": {
            "Phlix\\VoidBloom\\Tests\\": "tests/"
        }
    },
    "config": {
        "optimize-autoloader": true,
        "sort-packages": true
    },
    "scripts": {
        "phpstan": "vendor/bin/phpstan analyse -c phpstan.neon",
        "phpcs": "vendor/bin/phpcs --standard=phpcs.xml"
    }
}
